COMMON_RULES = [
    "只根据转写与确认过的历史背景整理，不补写未出现的事实、结论、责任人、日期、指标或原因。",
    "严格区分会议决定、已达成共识、倾向意见、个人建议、待确认事项和分歧意见。",
    "金额、日期、数量、性能指标、版本号、单位、阈值和范围必须保持原样。",
    "行动项包含任务、责任人、配合人、输出成果、完成日期、关闭标准和状态；缺失项写待确认。",
    "按议题和结论组织，不按发言顺序写流水账；语言直接、简洁、正式。",
]


def templates() -> list[dict[str, Any]]:
    return [{
        "id": row[0], "version": 1, "name": row[1], "category": row[2],
        "description": row[3], "focus": row[4], "structure": row[5],
        "special_rule": row[6],
        "sections": [part.strip("。 ") for part in row[5].split("→") if part.strip()],
        "common_rules": COMMON_RULES,
    } for row in _ROWS]


def get_template(template_id: str, version: int = 1) -> dict[str, Any] | None:
    return next((item for item in templates()
                 if item["id"] == str(template_id).zfill(2) and item["version"] == int(version)), None)
